// TH15 v1.00b Stage 2 Boss2 (nonspell), st02bs.ecl.txt:199-261.
// Card frame 0 = segment timerReset/segment start; the 120-frame opening buffer
// precedes the source entry. The source entry then spends its own 120 frames on
// movePosTime(90,9,0,96) + wait(60) + wait(60) before the first volley.
// Source window: setInterrupt(0,2400,2100,"BossCard2") -> 2100 frames from entry.

const TIME_LIMIT: int = 2224;
const OPENING_BUFFER: int = 120;
const TH15_BALL2: int = 432; // etSprite type 5 -> TH15_BALL2, color 4 (valid 0-15)

// Boss2_at: etAim(0,3) fixed-direction ring, one speed layer.
// Volley k uses dist F = 90-3k, ways G0+k, speed 1.5+0.05k, base angle A0+k*C.
// The pushed initial etSpeed(1.5 or 2.1) is overwritten by the loop's literal
// 1.5 before the first etOn, so every rank's first volley is 1.5.
// Birth EX ANIM(a=1): keeping only its position -= 4*velocity entry displacement
// (approved birth-phase omission), folded into the per-bullet spawn distance.
async sub burst(base: angle, turn: angle) {
    var rank: int = global(GVAR_RANK);
    var f: fx = 90fx;
    var g: int = 10;
    if rank == RANK_LUNATIC { g = 12; }        // diffI($G,10,10,10,12)
    var h: fx = 1.5fx;
    var n: int = 16;                            // diffI($I,16,32,38,38)
    if rank == RANK_NORMAL { n = 32; }
    if rank >= RANK_HARD { n = 38; }
    var gap: int = 6;                           // E 8, N/H/L 6
    if rank == RANK_EASY { gap = 8; }
    var a: angle = base;
    sh_reset(0);
    sh_sprite(0, TH15_BALL2, 4);
    sh_ring(0, 1);
    sh_aim(0, 0);
    sh_offset(0, 0fx, -8fx);                    // etOffset(0,0,-8)
    for k in 0..n {
        sh_dist(0, f - 4fx * h);                // etDist(F) plus ANIM entry -4*speed
        sh_count(0, g, 1);
        sh_speed(0, h, 0fx);
        sh_angle(0, a, 0deg);
        sh_fire(0);
        f = f - 3fx;
        a = a + turn;
        g = g + 1;
        h = h + 0.05fx;
        wait(gap);
    }
}

// moveRand(60,4,1.0) under moveLimit(0,96,280,48): position clamp
// x in [-140,140], y in [72,120]; direction inner box x +-70, y [84,108];
// speed ramps 1-k/60 over 60 steps. Owns self_int(0) (step count) and
// self_fx(0/1) (unit direction); burst tasks never use these slots.
sub arm_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 72fx { ny = 72fx; }
    if ny > 120fx { ny = 120fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub move_rand_once() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 84fx {
        if a < 0 { a = -a; }
    } else if $self_y > 108fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    arm_step();
}

sub move_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        arm_step();
    }
}

async sub boss_main() {
    set_invuln(65535);
    set_hitbox(24fx);                           // Boss context setHitbox(48,48), radius 48*0.5
    set_hurtbox(20fx);                          // Boss context setHurtbox(40,40), radius 40*0.5
    move_to(90, 0fx, 96fx, EASE_QUAD_IN_OUT);   // movePosTime(90,9,0,96) from entry (0,128)
    wait(60);
    wait(60);
    // Boss2_1188 loop. Boss2_at is called async; its B parameter is unused
    // (the initial etAngle literal is overwritten by the loop's etAngle before etOn).
    loop {
        spawn burst(-90deg, -4deg);
        wait(160);
        move_rand_once();
        move_wait(60);
        spawn burst(-90deg, 4deg);
        wait(160);
        move_rand_once();
        move_wait(60);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // Entry state from Boss:8-48: position (0,128), full boss HP pool (lifeSet 14200).
    _ = spawn_enemy(0fx, 128fx, 14200, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
